
    window.SOUNDS_BASE64 = {
    panicAlarm: '',
    platePass: '',
    plateFail: '',
    callAlert: '',
    warrantAlert: '',
    StartupSFX: ' ',
    LoginAccessDenied: ' ',
    LoginIncorrect: ' ',
    LoginPageCorrect: ' ',
    };

console.log('[SOUNDS] ✅ Loaded');
console.log('[SOUNDS] 🔧 Processing base64 data...');
window.SOUNDS = {};
for (const [key, base64] of Object.entries(window.SOUNDS_BASE64)) {
    const audioType = base64.trim().startsWith('UklGR') ? 'audio/wav' : 'audio/mpeg';
    window.SOUNDS[key] = `data:${audioType};base64,${base64.trim()}`;
}
console.log('[SOUNDS] ✅ Ready! Available sounds:', Object.keys(window.SOUNDS).join(', '));
